std::vector<Polygon2d> result;
for (auto it = arr.faces_begin(); it != arr.faces_end(); ++it) {
    if (!it->is_unbounded()) {
        Polygon2d polygon;
        auto he = it->outer_ccb();
        do {
            polygon.push_back(std::make_pair(he->source()->point().x(), he->source()->point().y()));
            he = he->next();
        } while (he != it->outer_ccb());
        result.push_back(polygon);
    }
}
return result;

